const cvUrl = $('Webhook').item.json.body.inputs.cv_url;

// Extract filePath using string methods
let filePath = '';
if (cvUrl.includes('filePath=')) {
  filePath = cvUrl.split('filePath=')[1];
  // Remove any additional query parameters
  if (filePath.includes('&')) {
    filePath = filePath.split('&')[0];
  }
  // Decode URL encoding
  filePath = decodeURIComponent(filePath);
}

return [{
  json: {
    filePath: filePath,
    fileName: filePath.split('/').pop()
  }
}];

